// Extract the video ID from the URL (watch, youtu.be, /live/, /shorts/, /embed/ or a bare ID)
const form = $('Livestream form').first().json;
const raw = String(form['YouTube URL'] || '').trim();

const patterns = [
  /(?:[?&]v=|\/live\/|\/shorts\/|\/embed\/|youtu\.be\/)([A-Za-z0-9_-]{11})/,
  /^([A-Za-z0-9_-]{11})$/,
];
let videoId = null;
for (const p of patterns) {
  const m = raw.match(p);
  if (m) { videoId = m[1]; break; }
}
if (!videoId) {
  throw new Error('Could not find a video ID in the URL: ' + raw);
}

return [{
  json: {
    video_id: videoId,
    url: `https://www.youtube.com/watch?v=${videoId}`,
    date_input: String(form['Stream date'] || '').trim(),
    language: form['Caption language'] || 'vi',
  },
}];

// Group the transcript into ~30-second lines stamped [hh:mm:ss], then into 20-minute sections
const LINE_MS = 30 * 1000;
const CHUNK_MS = 20 * 60 * 1000;
const TZ = 'Asia/Ho_Chi_Minh';

const res = $input.first().json;
if (res.status === 'queued' || res.status === 'active') {
  throw new Error('Supadata was still processing after 15 minutes. Try again later.');
}
if (res.status === 'failed') {
  throw new Error('Supadata processing failed: ' + JSON.stringify(res.error));
}
if (!Array.isArray(res.content) || res.content.length === 0) {
  throw new Error('Could not get a transcript: ' + (res.message || res.error || JSON.stringify(res).slice(0, 300)));
}

const video = $('Prepare video').first().json;

// Details from the YouTube Data API (may be missing if no API key is configured)
let yt = null;
try {
  const ytJson = $('YouTube: video details').first().json;
  yt = (ytJson && Array.isArray(ytJson.items) && ytJson.items[0]) || null;
} catch (e) { yt = null; }

const startIso = yt?.liveStreamingDetails?.actualStartTime || yt?.snippet?.publishedAt || null;

// Stream date in Vietnam time: a date typed into the form wins
let streamDate = null;
if (video.date_input) {
  let d = DateTime.fromISO(video.date_input, { zone: TZ });
  if (!d.isValid) d = DateTime.fromFormat(video.date_input, 'dd/MM/yyyy', { zone: TZ });
  if (!d.isValid) throw new Error('Invalid date entered: ' + video.date_input);
  streamDate = d.toISODate();
} else if (startIso) {
  streamDate = DateTime.fromISO(startIso).setZone(TZ).toISODate();
}
if (!streamDate) {
  throw new Error('Could not determine the stream date. Enter a date in the form or configure the YouTube API key.');
}

const fmt = (ms) => {
  const s = Math.floor(ms / 1000);
  const h = String(Math.floor(s / 3600)).padStart(2, '0');
  const m = String(Math.floor((s % 3600) / 60)).padStart(2, '0');
  const sec = String(s % 60).padStart(2, '0');
  return `${h}:${m}:${sec}`;
};

const segs = res.content
  .filter((c) => c && typeof c.text === 'string' && c.text.trim())
  .map((c) => ({ text: c.text.replace(/\s+/g, ' ').trim(), offset: Number(c.offset) || 0, duration: Number(c.duration) || 0 }))
  .sort((a, b) => a.offset - b.offset);

// 1) Group into ~30-second lines
const lines = [];
let cur = null;
for (const s of segs) {
  if (!cur || s.offset - cur.start >= LINE_MS) {
    if (cur) lines.push(cur);
    cur = { start: s.offset, parts: [] };
  }
  cur.parts.push(s.text);
}
if (cur) lines.push(cur);

// 2) Group the lines into 20-minute sections
const groups = new Map();
for (const l of lines) {
  const k = Math.floor(l.start / CHUNK_MS);
  if (!groups.has(k)) groups.set(k, []);
  groups.get(k).push(`[${fmt(l.start)}] ${l.parts.join(' ')}`);
}

const last = segs[segs.length - 1];
const endMs = last.offset + last.duration;

let durationSeconds = null;
if (yt?.contentDetails?.duration) {
  const dur = Duration.fromISO(yt.contentDetails.duration);
  if (dur.isValid) durationSeconds = Math.round(dur.as('seconds'));
}
if (!durationSeconds) durationSeconds = Math.round(endMs / 1000);

const keys = [...groups.keys()].sort((a, b) => a - b);
const meta = {
  video_id: video.video_id,
  url: video.url,
  stream_date: streamDate,
  started_at: startIso,
  title: yt?.snippet?.title || `Livestream ${streamDate}`,
  duration_seconds: durationSeconds,
  language: res.lang || video.language,
};

return keys.map((k, i) => ({
  json: {
    ...meta,
    section: i + 1,
    section_count: keys.length,
    start: fmt(k * CHUNK_MS),
    end: fmt(Math.min((k + 1) * CHUNK_MS, endMs)),
    content: groups.get(k).join('\n'),
  },
}));

// Join the section summaries (in order) into one text for the overall summary
const sections = $('Split into 20-minute sections').all();
const outs = $input.all();

const sectionSummaries = sections.map((s, i) => ({
  section: s.json.section,
  start: s.json.start,
  end: s.json.end,
  summary: String(outs[i]?.json?.text || '').trim(),
}));

const { content, section, start, end, ...meta } = sections[0].json;

const sectionsText = sectionSummaries
  .map((d) => `### Section ${d.section} (${d.start} – ${d.end})\n${d.summary}`)
  .join('\n\n');

return [{ json: { ...meta, section_summaries: sectionSummaries, sections_text: sectionsText } }];

// Build one record for the livestreams table
const g = $('Merge sections').first().json;
const transcript = $('Split into 20-minute sections').all().map((s) => s.json.content).join('\n');

return [{
  json: {
    video_id: g.video_id,
    stream_date: g.stream_date,
    started_at: g.started_at,
    title: g.title,
    url: g.url,
    duration_seconds: g.duration_seconds,
    language: g.language,
    summary: String($input.first().json.text || '').trim(),
    section_summaries: JSON.stringify(g.section_summaries),
    transcript,
  },
}];
